```python
import requests
import json
import time
import hashlib
import threading

class MinerClient:
    def __init__(self, node_url, miner_id):
        self.node_url = node_url
        self.miner_id = miner_id
        self.worker_thread = None
        self.running = False

    def get_work(self):
        try:
            response = requests.get(f"{self.node_url}/getwork")
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            print(f"Error al obtener trabajo: {e}")
            return None

    def submit_solution(self, solution):
        payload = {
            "solution": solution,
            "miner_id": self.miner_id
        }
        try:
            response = requests.post(f"{self.node_url}/submit", json=payload)
            response.raise_for_status()
            print("Solución enviada con éxito.")
        except requests.RequestException as e:
            print(f"Error al enviar solución: {e}")

    def mine(self):
        while self.running:
            work = self.get_work()
            if not work:
                time.sleep(5)
                continue

            target = work.get('target')
            data = work.get('data')
            nonce = 0
            while nonce < 1000000:
                hash = hashlib.sha256((data + str(nonce)).encode()).hexdigest()
                if hash < target:
                    self.submit_solution(nonce)
                    break
                nonce += 1
            time.sleep(1)

    def start_mining(self):
        self.running = True
        self.worker_thread = threading.Thread(target=self.mine)
        self.worker_thread.start()

    def stop_mining(self):
        self.running = False
        if self.worker_thread:
            self.worker_thread.join()

# Ejemplo de uso
if __name__ == "__main__":
    client = MinerClient("http://localhost:3000", "Miner001")
    client.start_mining()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        client.stop_mining()
```

